import { ChangeDetectorRef, Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

type CommentNode = {
  id: string;
  text: string;
  deleted: boolean;
  children: CommentNode[];
};

function insertReply(nodes: CommentNode[], parentId: string, reply: CommentNode): CommentNode[] {
  return nodes.map((node) =>
    node.id === parentId
      ? { ...node, children: [...node.children, reply] }
      : { ...node, children: insertReply(node.children, parentId, reply) }
  );
}

function deleteFromTree(nodes: CommentNode[], id: string): CommentNode[] {
  return nodes.flatMap((node) => {
    if (node.id === id) {
      return node.children.length ? [{ ...node, text: '[deleted]', deleted: true }] : [];
    }
    const children = deleteFromTree(node.children, id);
    // A placeholder has nothing left to show once its last reply is gone.
    if (node.deleted && children.length === 0) return [];
    return [{ ...node, children }];
  });
}

function containsComment(node: CommentNode, id: string): boolean {
  return node.children.some((child) => child.id === id || containsComment(child, id));
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  private readonly changeDetector = inject(ChangeDetectorRef);

  comments: CommentNode[] = [
    { id: '1', text: 'First comment', deleted: false, children: [] }
  ];

  topDraft = '';
  activeReplyId: string | null = null;
  drafts: Record<string, string> = {};
  hiddenIds: Record<string, boolean> = {};
  threadStatus = '';

  private nextId = 2;

  addTop(): void {
    const text = this.topDraft.trim();
    if (!text) return;
    this.comments = [{ id: this.makeId(), text, deleted: false, children: [] }, ...this.comments];
    this.topDraft = '';
  }

  openReply(id: string): void {
    this.activeReplyId = id;
    this.focusAfterRender(`reply-input-${id}`);
  }

  setDraft(id: string, value: string): void {
    this.drafts[id] = value;
  }

  cancelReply(id: string): void {
    delete this.drafts[id];
    this.activeReplyId = null;
    this.focusAfterRender(`reply-button-${id}`);
  }

  submitReply(id: string, event?: Event): void {
    event?.preventDefault();
    const text = (this.drafts[id] ?? '').trim();
    if (!text) return;

    this.comments = insertReply(this.comments, id, {
      id: this.makeId(),
      text,
      deleted: false,
      children: []
    });
    this.hiddenIds[id] = false;
    delete this.drafts[id];
    this.activeReplyId = null;
    this.threadStatus = 'Reply added';
    this.focusAfterRender(`reply-button-${id}`);
  }

  toggleReplies(node: CommentNode): void {
    const hide = !this.hiddenIds[node.id];
    this.hiddenIds[node.id] = hide;
    if (hide && this.activeReplyId && containsComment(node, this.activeReplyId)) {
      this.activeReplyId = null;
    }
  }

  deleteComment(id: string): void {
    this.comments = deleteFromTree(this.comments, id);
    delete this.drafts[id];
    if (this.activeReplyId === id) this.activeReplyId = null;
    this.threadStatus = 'Comment deleted';
    this.focusAfterRender('comment-box');
  }

  replyCount(node: CommentNode): number {
    return node.children.reduce((total, child) => total + 1 + this.replyCount(child), 0);
  }

  private makeId(): string {
    return String(this.nextId++);
  }

  // The element to focus may only exist after this render, so render first.
  private focusAfterRender(elementId: string): void {
    this.changeDetector.detectChanges();
    document.getElementById(elementId)?.focus();
  }
}

